(function(){try{var st=document.createElement('style');st.textContent='.syl{display:flex;flex-direction:column;align-items:center;gap:8px;margin:14px 0;padding:12px;border-radius:16px;background:var(--gn-bg)}.syl .sw{display:flex;flex-wrap:wrap;justify-content:center;font:800 2rem/1.1 var(--display)}.syl .sw span{padding:2px 3px;border-radius:8px;transition:background .25s,color .25s,transform .25s}.syl .sw span.on{background:var(--sun);color:#3b2b00;transform:translateY(-4px) scale(1.12)}.syl .sw span.hard{text-decoration:underline 3px var(--verb);text-underline-offset:5px}.syl .sw span.sep::after{content:"–";color:var(--soft);margin:0 2px}.syl.full .sw span.sep::after{content:""}.syl.full .sw span{background:var(--pro-bg)}.syl .sb{display:flex;gap:8px}.syl button{padding:8px 14px;border-radius:12px;font-weight:800;background:var(--gn);color:#fff}.syl button.g2{background:var(--card);color:var(--ink);border:2px solid var(--line)}';document.head.appendChild(st);}catch(e){}})();
window.mrSyl=function(){
  var sp=function(t){try{say(t)}catch(e){}};
  document.querySelectorAll('.syl').forEach(function(b){
    var s=b.dataset.s.split('|'),m=b.dataset.m;
    b.innerHTML='<div class="sw">'+s.map(function(x,i){return '<span class="'+(i<s.length-1?'sep ':'')+(m!==undefined&&+m===i?'hard':'')+'">'+x+'</span>'}).join('')+'</div><div class="sb"><button class="cut">✂ Découper</button><button class="g2 hear">🔊 Le mot</button></div>';
    var ss=b.querySelectorAll('.sw span'),busy=0,w=function(ms){return new Promise(function(r){setTimeout(r,ms)})};
    b.querySelector('.hear').onclick=function(){sp(b.dataset.w)};
    if(m!==undefined)ss[+m].onclick=function(){sp(s[+m]);};
    b.querySelector('.cut').onclick=async function(){if(busy)return;busy=1;b.classList.remove('full');
      for(var i=0;i<ss.length;i++){ss[i].classList.add('on');sp(s[i]);await w(900);ss[i].classList.remove('on');}
      await w(250);for(var i=0;i<ss.length;i++){ss[i].classList.add('on');await w(260);ss[i].classList.remove('on');}
      b.classList.add('full');sp(b.dataset.w);busy=0;};
  });
};

