window.MRX=window.MRX.concat([{"id": "ml-2", "name": "L'expédition des mots géants", "sub": "Lire les mots longs", "cls": "gn", "badge": "📖", "steps": [{"t": "teach", "title": "L'expédition des mots géants", "say": "Mission : aider l'exploratrice Zoé à lire les mots cachés dans son carnet. Zoé appuie sur le bouton Découper. Les syllabes s'allument une à une, puis tu relis le mot entier.", "html": "<p class=\"big\">Mission : aider l'exploratrice Zoé à lire les mots cachés dans son carnet.</p><p>Appuie sur « Découper » : les syllabes s'allument une à une, puis tu relis le mot entier.</p><div class=\"syl\" data-s=\"mé|di|ca|ment\" data-w=\"médicament\"></div>", "js": "syl", "chk": {"q": "Après les syllabes, je…", "o": ["relis le mot entier", "m'arrête"], "a": 0}}, {"t": "teach", "title": "Je découvre : parasol", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"pa|ra|sol\" data-w=\"parasol\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : avalanche", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"a|va|lanche\" data-w=\"avalanche\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : écrivain", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"é|cri|vain\" data-w=\"écrivain\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : vocabulaire", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"vo|ca|bu|laire\" data-w=\"vocabulaire\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : enveloppe", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"en|ve|loppe\" data-w=\"enveloppe\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : invitation", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"in|vi|ta|tion\" data-w=\"invitation\"></div>", "js": "syl"}, {"t": "teach", "title": "Je découvre : calculatrice", "say": "Écoute le mot, puis appuie sur Découper.", "html": "<p>Appuie sur « Découper », lis chaque syllabe éclairée, puis relis le mot entier.</p><div class=\"syl\" data-s=\"cal|cu|la|trice\" data-w=\"calculatrice\"></div>", "js": "syl"}, {"t": "choice", "q": "Combien de syllabes dans « parasol » ?", "opts": ["2", "3", "4"], "ans": 1, "ok": "Oui : pa-ra-sol, 3 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "Combien de syllabes dans « vocabulaire » ?", "opts": ["2", "3", "4"], "ans": 2, "ok": "Oui : vo-ca-bu-laire, 4 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "Combien de syllabes dans « enveloppe » ?", "opts": ["2", "3", "4"], "ans": 1, "ok": "Oui : en-ve-loppe, 3 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "Combien de syllabes dans « calculatrice » ?", "opts": ["2", "3", "4"], "ans": 2, "ok": "Oui : cal-cu-la-trice, 4 syllabes.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["sol", "pa", "ra"], "ans": "pa-ra-sol", "j": "-", "ok": "Bravo : pa-ra-sol → parasol", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["vain", "é", "cri"], "ans": "é-cri-vain", "j": "-", "ok": "Bravo : é-cri-vain → écrivain", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["tion", "in", "ta", "vi"], "ans": "in-vi-ta-tion", "j": "-", "ok": "Bravo : in-vi-ta-tion → invitation", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "build", "q": "Remets les syllabes dans l'ordre.", "words": ["laire", "vo", "bu", "ca"], "ans": "vo-ca-bu-laire", "j": "-", "ok": "Bravo : vo-ca-bu-laire → vocabulaire", "ko": "Lis les morceaux un par un. Recommence."}, {"t": "choice", "q": "cal – cu – la – trice, c'est…", "opts": ["calculatrice", "caravane", "chocolat"], "ans": 0, "ok": "Oui : calculatrice.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "en – ve – loppe, c'est…", "opts": ["enveloppe", "avalanche", "écrivain"], "ans": 0, "ok": "Oui : enveloppe.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "choice", "q": "a – va – lanche, c'est…", "opts": ["aventure", "avalanche", "invitation"], "ans": 1, "ok": "Oui : avalanche.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "teach", "title": "Je garde les groupes de lettres ensemble", "say": "Certains morceaux contiennent plusieurs lettres qui travaillent ensemble. On les garde ensemble pendant la lecture. Vain dans écrivain. Tion dans invitation. Trice dans calculatrice.", "html": "<p class=\"big\">Certains morceaux contiennent plusieurs lettres qui travaillent ensemble. On les garde ensemble pendant la lecture.</p><div class=\"syl\" data-s=\"é|cri|vain\" data-w=\"écrivain\" data-m=\"2\"></div><div class=\"syl\" data-s=\"in|vi|ta|tion\" data-w=\"invitation\" data-m=\"3\"></div><div class=\"syl\" data-s=\"cal|cu|la|trice\" data-w=\"calculatrice\" data-m=\"3\"></div>", "js": "syl", "chk": {"q": "Dans « invitation », je garde ensemble…", "o": ["t-i-o-n", "tion"], "a": 1}}, {"t": "teach", "title": "Le carnet de Zoé", "say": "Zoé ouvre une enveloppe. Elle y trouve une invitation pour partir en avalanche ? Non : une invitation à découvrir le vocabulaire caché dans la montagne !", "html": "<p class=\"big\">Zoé ouvre une enveloppe.<br>Elle y trouve une invitation pour partir en avalanche ?<br>Non : une invitation à découvrir le vocabulaire caché dans la montagne !</p><div class=\"syl\" data-s=\"en|ve|loppe\" data-w=\"enveloppe\"></div><div class=\"syl\" data-s=\"in|vi|ta|tion\" data-w=\"invitation\"></div><div class=\"syl\" data-s=\"vo|ca|bu|laire\" data-w=\"vocabulaire\"></div>", "js": "syl"}, {"t": "choice", "q": "Qu'est-ce que Zoé trouve dans l'enveloppe ?", "opts": ["une avalanche", "une invitation", "une montagne"], "ans": 1, "ok": "Oui : une invitation.", "ko": "Compte les syllabes en tapant dans tes mains."}, {"t": "teach", "title": "Le geste à retenir", "say": "J'écoute le mot. Je lis les syllabes éclairées. Je relis le mot entier.", "html": "<p class=\"big\">J'écoute le mot.<br>Je lis les syllabes éclairées.<br>Je relis le mot entier.</p>", "js": "syl", "chk": {"q": "Après les syllabes éclairées, je…", "o": ["relis le mot entier", "passe au mot suivant"], "a": 0}}]}]);

